use super::kit::*;use crate::color::node_graph::{Graph,Node,INPUT};use crate::keyframe::Prop;
fn clip<'a>(s:&'a mut Session,a:&Value)->Result<&'a mut crate::model::Clip,String>{s.project.find_clip_mut(str_arg(a,"clip_id")?).ok_or("no clip".into())}
fn read_graph(s:&mut Session,a:&Value)->Result<Graph,String>{if let Some(id)=a.get("shared_graph_id").and_then(Value::as_str){if a.get("clip_id").is_some(){return Err("choose clip_id OR shared_graph_id".into())}s.project.grade_scopes.graphs.get(id).cloned().ok_or("missing shared graph".into())}else{Ok(clip(s,a)?.grade_graph.clone().unwrap_or_default())}}
fn write_graph(s:&mut Session,a:&Value,g:Option<Graph>)->Result<(),String>{if let Some(id)=a.get("shared_graph_id").and_then(Value::as_str){if a.get("clip_id").is_some(){return Err("choose clip_id OR shared_graph_id".into())}if !s.project.grade_scopes.graphs.contains_key(id){return Err("missing shared graph".into())}s.project.grade_scopes.graphs.insert(id.into(),g.ok_or("shared graph cannot be cleared; remove via scope tool")?);}else{clip(s,a)?.grade_graph=g;}Ok(())}
fn update(s:&mut Session,a:&Value,edit:impl FnOnce(&mut Graph)->Result<Value,String>)->Result<Value,String>{let mut g=read_graph(s,a)?;let result=edit(&mut g)?;g.validate(false)?;write_graph(s,a,Some(g))?;Ok(result)}
fn node<'a>(g:&'a mut Graph,a:&Value)->Result<&'a mut Node,String>{g.nodes.get_mut(str_arg(a,"node_id")?).ok_or("missing node".into())}
fn schema(extra:Vec<(&str,Value)>,required:&[&str])->Value{let mut p=vec![("clip_id",s("clip target, omit for shared graph")),("shared_graph_id",s("shared graph target, omit clip_id"))];p.extend(extra);let mut r=vec![];r.extend(required);obj(p,&r)}
pub fn commands()->Vec<Command>{vec![
Command{name:"evaluate_grade_graph_samples",description:"Evaluate clip graph on explicitly supplied RGBA float samples (not timeline media), returning pixels and actual node-cache stats. Up to4096pixels; same domains/time/seed as declared nodes. No project mutation.",mutates:false,schema:schema(vec![("rgba",json!({"type":"array","items":{"type":"number"}})),("time",n("clip-local seconds")),("seed",json!({"type":"integer","minimum":0}))],&["rgba"]),run:|ss,a|{let fps=ss.project.fps;let g=read_graph(ss,a)?;let d=a.get("rgba").and_then(Value::as_array).ok_or("rgba array")?;if d.is_empty()||d.len()%4!=0||d.len()>16384{return Err("1..4096RGBApixels".into())}let d=d.iter().map(|v|v.as_f64().filter(|v|v.is_finite()&&v.abs()<=f32::MAX as f64).map(|v|v as f32).ok_or("finiteRGBA".into())).collect::<Result<Vec<_>,String>>()?;let mut f=crate::effects::Frame{w:d.len()/4,h:1,d};let seed=match a.get("seed"){None=>0,Some(v)=>v.as_u64().ok_or("unsigned integerseed")?};let stats=g.apply(&mut f,opt_num(a,"time",0.),seed,fps)?;Ok(json!({"rgba":f.d,"cache":stats}))}},
Command{name:"inspect_grade_graph",description:"Read persisted per-clip grade DAG and topological plan. Input is reserved input. Serial grade, weighted-average parallel and ordered RGB layer mixers; graph follows existing clip effects, before masks/transforms. Node cache is evaluation-local, budgeted, not persistent frame cache.",mutates:false,schema:schema(vec![],&[]),run:|ss,a|{let g=read_graph(ss,a)?;Ok(json!({"order":g.validate(false)?,"graph":g,"effect_kinds":crate::color::node_graph::GRADES,"spatial_contract":"blur/sharpen process full branch canvas in order, mask after operation, first-input alpha restored. No commutativity/reordering.","lut_contract":"path OR inline cube_text, input domain clamps, generated interpolation error measured not globally bounded","domain":"same rendered clip domain unless explicitly wrapped","parallel":"normalized nonnegative weighted RGB average","layer":"first input base, later inputs RGB opacity blend in connection order; first weight ignored","alpha":"first input preserved"}))}},
Command{name:"set_grade_graph",description:"Replace or clear a full per-clip grade DAG. Complete JSON graph controls all node/edge/effect parameter/string/Prop keyframe/expression/mask/tracking fields and cache budget. Transactional acyclic validation; incomplete parked nodes permitted but reachable nodes must be connected when rendered.",mutates:true,schema:schema(vec![("graph",json!({"type":["object","null"]}))],&["graph"]),run:|ss,a|{let v=a.get("graph").ok_or("graph required")?;if v.is_null(){write_graph(ss,a,None)?;}else{let g:Graph=serde_json::from_value(v.clone()).map_err(|e|e.to_string())?;g.validate(false)?;write_graph(ss,a,Some(g))?;}Ok(json!({"ok":true}))}},
Command{name:"add_node",description:"Add a grade/parallel/layer node to a clip. Optional parent becomes first input; grade defaults to input. Mixers initially parked until fully connected/output selected. effect_kind from inspect_grade_graph supported grade list.",mutates:true,schema:schema(vec![("node_id",s("unique node identity, not input")),("parent",s("optional first input")),("kind",json!({"type":"string","enum":["grade","parallel","layer"]})),("effect_kind",s("grade effect kind")),("params",json!({"type":"object","additionalProperties":{"type":"number"}})),("strings",json!({"type":"object","additionalProperties":{"type":"string"}}))],&["node_id","kind"]),run:|ss,a|update(ss,a,|g|{let id=str_arg(a,"node_id")?.to_string();if g.nodes.contains_key(&id)||id==INPUT{return Err("node identity already exists/reserved".into())}let kind=str_arg(a,"kind")?.to_string();let parent=a.get("parent").and_then(Value::as_str).or(if kind=="grade"{Some(INPUT)}else{None});let inputs=parent.map(|p|vec![p.to_string()]).unwrap_or_default();let weights=inputs.iter().map(|_|Prop::new(1.)).collect();let effect=if kind=="grade"{let params=a.get("params").map(|v|serde_json::from_value::<std::collections::BTreeMap<String,f64>>(v.clone())).transpose().map_err(|e|e.to_string())?.unwrap_or_default().into_iter().map(|(k,v)|(k,Prop::new(v))).collect();let strings=serde_json::from_value(a.get("strings").cloned().unwrap_or(json!({}))).map_err(|e|e.to_string())?;Some(crate::model::Effect{id:id.clone(),kind:str_arg(a,"effect_kind")?.into(),params,strings})}else{None};g.nodes.insert(id.clone(),Node{id:id.clone(),kind,inputs,effect,weights,mask:None,bypass:false});Ok(json!({"node_id":id}))})},
Command{name:"connect_nodes",description:"Connect/replace ordered input slot (0-based) on destination node, optional weight. Missing slot indices rejected; cycles/missing sources rejected. Serial grade accepts exactly one input; mixer first input is base for masks/layer alpha.",mutates:true,schema:schema(vec![("source",s("input or node")),("node_id",s("destination")),("slot",json!({"type":"integer","minimum":0,"maximum":15})),("weight",n("0..1 default1"))],&["source","node_id","slot"]),run:|ss,a|update(ss,a,|g|{let n=node(g,a)?;let i=a.get("slot").and_then(Value::as_u64).ok_or("integer slot")? as usize;if i>n.inputs.len()||i>=16{return Err("slot must replace or append next input".into())}let weight=opt_num(a,"weight",1.);if !(0. ..=1.).contains(&weight){return Err("weight0..1".into())}let src=str_arg(a,"source")?.into();if i==n.inputs.len(){n.inputs.push(src);n.weights.push(Prop::new(weight));}else{n.inputs[i]=src;n.weights[i]=Prop::new(weight);}Ok(json!({"ok":true}))})},
Command{name:"disconnect_nodes",description:"Remove ordered input slot and its weight. Reachable incomplete nodes error at render; graph edits remain inspectable.",mutates:true,schema:schema(vec![("node_id",s("destination")),("slot",json!({"type":"integer","minimum":0,"maximum":15}))],&["node_id","slot"]),run:|ss,a|update(ss,a,|g|{let n=node(g,a)?;let i=a.get("slot").and_then(Value::as_u64).ok_or("integer slot")? as usize;if i>=n.inputs.len(){return Err("missing slot".into())}n.inputs.remove(i);n.weights.remove(i);Ok(json!({"ok":true}))})},
Command{name:"remove_grade_node",description:"Delete a disconnected node; refuses removal while referenced by connections/output. Reconnect/output first.",mutates:true,schema:schema(vec![("node_id",s("node"))],&["node_id"]),run:|ss,a|update(ss,a,|g|{let id=str_arg(a,"node_id")?;if g.output==id||g.nodes.values().any(|n|n.inputs.iter().any(|x|x==id)){return Err("node still referenced".into())}g.nodes.remove(id).ok_or("missing node")?;Ok(json!({"ok":true}))})},
Command{name:"set_grade_output",description:"Select input or node as graph output; does not reorder/remove linear effects.",mutates:true,schema:schema(vec![("node_id",s("input or output node"))],&["node_id"]),run:|ss,a|update(ss,a,|g|{g.output=str_arg(a,"node_id")?.into();Ok(json!({"ok":true}))})},
Command{name:"set_grade_node",description:"Replace one complete node by identity, including effect kind/strings, bypass, ordered edges/weights, numeric Prop keyframes/expressions and mask. Full JSON node is read via inspect_grade_graph; validation is transactional.",mutates:true,schema:schema(vec![("node",json!({"type":"object"}))],&["node"]),run:|ss,a|update(ss,a,|g|{let n:Node=serde_json::from_value(a.get("node").ok_or("node required")?.clone()).map_err(|e|e.to_string())?;if !g.nodes.contains_key(&n.id){return Err("missing node".into())}g.nodes.insert(n.id.clone(),n);Ok(json!({"ok":true}))})},
Command{name:"set_node_param",description:"Set full numeric Prop (base/keys/ease/bezier/expr) on grade effect parameter. Strings/effect kind via set_grade_node. No hidden parameter or animation state.",mutates:true,schema:schema(vec![("node_id",s("grade node")),("parameter",s("effect numeric param")),("property",json!({"type":"object"}))],&["node_id","parameter","property"]),run:|ss,a|update(ss,a,|g|{let e=node(g,a)?.effect.as_mut().ok_or("grade effect required")?;let p:Prop=serde_json::from_value(a.get("property").ok_or("property required")?.clone()).map_err(|e|e.to_string())?;e.params.insert(str_arg(a,"parameter")?.into(),p);Ok(json!({"ok":true}))})},
Command{name:"set_node_mask",description:"Set/clear full MaskLayer on node: rect/ellipse/path/linear/radial/luma/color/hsl/alpha/noise keys supported. Local coverage blends node output against first input. No cross-clip matte references.",mutates:true,schema:schema(vec![("node_id",s("node")),("mask",json!({"type":["object","null"]}))],&["node_id","mask"]),run:|ss,a|update(ss,a,|g|{node(g,a)?.mask=serde_json::from_value(a.get("mask").ok_or("mask required")?.clone()).map_err(|e|e.to_string())?;Ok(json!({"ok":true}))})},
Command{name:"grade_node_tracking",description:"Import explicit tracker samples into node mask cx/cy/rot keyframes on clip-local clock. Samples time,cx,cy,rot (normalized position, degree rotation). Does NOT solve tracking; use track_point/planar then supply verified samples. Path point keys via set_node_mask.",mutates:true,schema:schema(vec![("node_id",s("masked node")),("samples",json!({"type":"array","items":{"type":"object","properties":{"time":{"type":"number"},"cx":{"type":"number"},"cy":{"type":"number"},"rot":{"type":"number"}},"required":["time","cx","cy"]}}))],&["node_id","samples"]),run:|ss,a|update(ss,a,|g|{let m=node(g,a)?.mask.as_mut().ok_or("node mask required")?;if !["rect","ellipse"].contains(&m.kind.as_str()){return Err("trackingcx/cy requires rect/ellipse mask; path pointkeys via set_node_mask".into())}let samples=a.get("samples").and_then(Value::as_array).ok_or("samples array")?;if samples.is_empty()||samples.len()>10000{return Err("1..10000samples".into())}for v in samples{let t=num_arg(v,"time")?;if t<0.||!t.is_finite(){return Err("finite nonnegative clip-local time".into())}for k in ["cx","cy","rot"]{let x=if k=="rot"{opt_num(v,k,0.)}else{num_arg(v,k)?};if !x.is_finite(){return Err("finite tracking sample".into())}m.props.entry(k.into()).or_insert(Prop::new(x)).set_key(t,x,crate::keyframe::Ease::Linear);}}Ok(json!({"samples":samples.len(),"tracking":"imported coordinates, no solve"}))})}
]}
